import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor min_reduce_forward(torch::Tensor x, int64_t dim);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
#include <vector>

using namespace cute;

template <typename T>
__global__ void min_reduce_kernel(
    const T* __restrict__ X,
    T* __restrict__ Y,
    int outer, int reduce, int inner)
{
  int o = blockIdx.y;
  int i = blockIdx.x * blockDim.x + threadIdx.x;

  if (o >= outer || i >= inner) return;

  // View the (reduce, inner) slice for this "outer" index as a CuTe tensor.
  // Since input is contiguous with logical shape (outer, reduce, inner),
  // the strides for a fixed outer index are (inner, 1).
  const T* base_ptr = X + (int64_t)o * (int64_t)reduce * (int64_t)inner;
  auto mX = make_tensor(
      make_gmem_ptr(base_ptr),
      make_shape(reduce, inner),
      make_stride(inner, 1)
  );

  T minv = mX(0, i);
  #pragma unroll 4
  for (int r = 1; r < reduce; ++r) {
    T v = mX(r, i);
    minv = (v < minv) ? v : minv;
  }

  Y[(int64_t)o * (int64_t)inner + i] = minv;
}

torch::Tensor min_reduce_forward(torch::Tensor x, int64_t dim) {
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");

  auto x_c = x.contiguous();
  int64_t ndim = x_c.dim();
  if (dim < 0) dim += ndim;
  TORCH_CHECK(dim >= 0 && dim < ndim, "dim out of range");

  int64_t outer = 1;
  int64_t inner = 1;
  for (int64_t d = 0; d < dim; ++d) outer *= x_c.size(d);
  int64_t reduce = x_c.size(dim);
  for (int64_t d = dim + 1; d < ndim; ++d) inner *= x_c.size(d);

  std::vector<int64_t> out_shape;
  out_shape.reserve(ndim - 1);
  for (int64_t d = 0; d < ndim; ++d) {
    if (d != dim) out_shape.push_back(x_c.size(d));
  }

  auto y = torch::empty(out_shape, x_c.options());

  const int threads = 256;
  dim3 block(threads);
  dim3 grid((unsigned)((inner + threads - 1) / threads), (unsigned)outer);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  min_reduce_kernel<float><<<grid, block, 0, stream>>>(
      x_c.data_ptr<float>(),
      y.data_ptr<float>(),
      (int)outer, (int)reduce, (int)inner
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "min_reduce_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

min_reduce_ext = load_inline(
    name="cute_min_reduce_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["min_reduce_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/root/cutegen_test/cutegen/cutlass/include",
        "/root/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs min reduction over a specific dimension,
    implemented with a custom CUDA kernel using CuTe tensors.
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim
        self._ext = min_reduce_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.min_reduce_forward(x.contiguous(), int(self.dim))

